1: /**
2:  * Load prompt section markdown files.
3:  *
4:  * Sections are read from disk at module load. The package build copies these
5:  * files to dist/prompt/sections so plain Node ESM can import core without a
6:  * custom .md loader.
7:  */
8: 
9: import { readFileSync } from "node:fs";
10: 
11: function readSectionFile(name: string): string {
12:   return readFileSync(new URL(`./sections/${name}.md`, import.meta.url), "utf-8");
13: }
14: 
15: const BUILTIN_SECTIONS: Record<string, string> = {
16:   "harness-base": readSectionFile("harness-base"),
17:   base: readSectionFile("base"),
18:   orchestration: readSectionFile("orchestration"),
19:   browser: readSectionFile("browser"),
20:   tone: readSectionFile("tone"),
21:   "context-notes": readSectionFile("context-notes"),
22: };
23: 
24: /**
25:  * Read a named prompt section. Returns the trimmed markdown content.
26:  * Contributed (module) sections win over built-ins; throws on unknown names.
27:  */
28: export function loadSection(name: string, sections?: Readonly<Record<string, string>>): string {
29:   const contributed = sections?.[name];
30:   if (contributed !== undefined) return contributed.trim();
31: 
32:   const builtin = BUILTIN_SECTIONS[name];
33:   if (builtin !== undefined) return builtin.trim();
34: 
35:   const available = Object.keys(BUILTIN_SECTIONS).join(", ");
36:   throw new Error(`Unknown prompt section "${name}". Available sections: ${available}`);
37: }
38: 
39: /**
40:  * Load multiple sections and join them with double newlines.
41:  */
42: export function loadSections(
43:   names: readonly string[],
44:   sections?: Readonly<Record<string, string>>,
45: ): string {
46:   return names.map((name) => loadSection(name, sections)).join("\n\n");
47: }
48: 
49: /**
50:  * List the built-in section names.
51:  */
52: export function availableSections(): string[] {
53:   return [...Object.keys(BUILTIN_SECTIONS)];
54: }

